import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import test from "node:test";
test("emits the versioned JSON status contract", () => {
  const cli = fileURLToPath(new URL("../bin/status.mjs", import.meta.url));
  const lines = execFileSync(process.execPath, [cli], { encoding: "utf8" }).trim().split(/\r?\n/);
  assert.equal(lines.length, 1);
  assert.deepEqual(JSON.parse(lines[0]), { schemaVersion: 1, kind: "status", ok: true });
});

