import { DatabaseSync } from "node:sqlite";
export const saveStatus = (file, status) => {
  const db = new DatabaseSync(file);
  db.exec("CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY, status TEXT NOT NULL)");
  db.prepare("INSERT OR REPLACE INTO state (id, status) VALUES (1, ?)").run(status);
  db.close();
};
export const loadStatus = (file) => {
  const db = new DatabaseSync(":memory:");
  db.exec("CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY, status TEXT NOT NULL)");
  const row = db.prepare("SELECT status FROM state WHERE id = 1").get();
  db.close();
  return row?.status;
};

