import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { loadStatus, saveStatus } from "../src/status-store.mjs";
test("resumes persisted state after reopening SQLite", async () => {
  const directory = await mkdtemp(path.join(os.tmpdir(), "representative-sqlite-"));
  try {
    const file = path.join(directory, "state.sqlite");
    saveStatus(file, "waiting_approval");
    assert.equal(loadStatus(file), "waiting_approval");
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
});

