import assert from "node:assert/strict";
import test from "node:test";
import { applyVersionedUpdate } from "../src/versioned-state.mjs";
test("rejects a stale concurrent update", () => {
  const state = { revision: 2, value: "concurrent" };
  assert.equal(applyVersionedUpdate(state, 1, "stale"), false);
  assert.deepEqual(state, { revision: 2, value: "concurrent" });
});

